import Foundation

/// JWK -> PKCS#1 DER fixtures generated with Node 22:
///
///  - `rsa4096JwkJson` is the EXACT private-key JWK contained in
///    WebVectors.encPrivateKey (decrypted with the derived key), i.e. the
///    real thing the app must convert at unlock time.
///  - `rsa4096Pkcs1DerBase64` is Node's
///    createPrivateKey({format:'jwk'}).export({type:'pkcs1',format:'der'})
///    for that JWK — the byte-exact DER SecKeyCreateWithData expects.
///  - The rsa2048 pair is an independent second fixture.
///
/// JWK JSON strings are stored base64-encoded to avoid escaping noise.
enum JwkFixtures {
    private static let rsa4096JwkJsonB64 = ""
    static var rsa4096JwkJson: String {
        String(data: Data(base64Encoded: rsa4096JwkJsonB64)!, encoding: .utf8)!
    }

    static let rsa4096Pkcs1DerBase64 = ""

    private static let rsa2048JwkJsonB64 = ""
    static var rsa2048JwkJson: String {
        String(data: Data(base64Encoded: rsa2048JwkJsonB64)!, encoding: .utf8)!
    }

    static let rsa2048Pkcs1DerBase64 = ""
}
